import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"兌","description":"高島易斷 - 兌","frontmatter":{"title":"兌","description":"高島易斷 - 兌"},"headers":[],"relativePath":"classics/takashima/058.md","filePath":"classics/takashima/058.md"}'),i={name:"classics/takashima/058.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h2 id="兌-1" tabindex="-1">兌 <a class="header-anchor" href="#兌-1" aria-label="Permalink to “兌”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>兌：亨，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《兌》本《乾》體，《坤》三動來入《乾》，成《兌》，《兌》之“亨，利貞”，即《乾》之德也。《乾》之四德配四時，《兌》主秋，在夏冬之間，得兼三德，獨不及元，故曰“兌亨，利貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>麗澤，兌，君子以朋友講習。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>“麗”者，連也，“麗澤”，謂兩澤相麗，是互相滋益也。朋友者，以互相講習為益，故象朋友；《兌》為口，故象講習。《論語》首章，以“學而時習’為悅，以有朋遠來為樂，是悅樂之要，莫大於“朋友講習”，此君子所以取其象於《兌》也。四爻曰“商兌”，商者，相與講論之義，其象亦取之麗澤。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運途平平，能得眾心，自然獲吉，惟逢三六之年，不利。</p><p>○　問營商：得人扶助，可以獲利。</p><p>○　問功名：賴朋友之力可成。</p><p>○　問戰徵：屯兵陂澤之地，宜於兩後營相約進攻，可以獲勝。</p><p>○　問婚姻：必是朋友舊好。</p><p>○　問家宅：宅臨澤水，宜與朋友同居。</p><p>○　問疾病：宜延相熟醫師並診，方可全愈。</p><p>○　問訟事：宜請朋友公評，不必涉訟。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初居卦首，體得《乾》剛，“和兌”者，即和悅也。《乾》曰利物和義，是和即《彖》之所謂利也。人當初交，便覺和衷相濟，以斯而悅，悅得其正矣，故吉。《傳》曰“行未疑也”，謂人私曲疑慮，每生於轉念，當其初，一片天心，固未嘗間以人慾也。“和兌”在初，順天而行，疑於何有？故不曰無疑，而曰“未疑”。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：運當初爻，以和為貴，萬事獲吉。</p><p>○　問戰徵：師克在和，民兵鹹悅，有不戰來歸之象。</p><p>○　問營商：《兌》為正秋，萬實告成，天地自然之美利也。營商得此，吉無不利。</p><p>○　問功名：得祥和之氣，吉。</p><p>○　問婚姻：有家室和平之樂。</p><p>○　問家宅：一門和氣，吉。</p><p>○　問行人：行當即歸，無疑。</p><p>○　問訟事：即可和解。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某來，請佔謀事成否？筮得《兌》之《困》。</p><p>斷曰：此卦一陰在二陽之上，以柔之卑，居剛之上。初爻得陽剛，剛以嚴，柔以和，以剛制柔，所謂和而不流者也。今足下佔謀事得此爻，爻屬於初，知其事尚在初起。“和”者，為彼此同心，和衷共濟。初與四應，四曰“商兌”，“商”謂商量也，正合謀事之意。初爻《傳》曰“行未疑”；謂其事必成無疑也；四爻《傳》曰“有慶”，謂其事成後，又有慶福也。足下安心從事可也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居下卦之中，以陽居陰，即《彖》所謂“剛中”也。二與五應，“孚兌”者，二孚於五，五亦孚於二，兩相孚，即兩相悅。二為臣，五為君，是君臣一心，相孚而相悅也，故吉。夫上下之心不相孚，則上下必不相悅，是以有悔，既得其孚，悔自亡矣。《象傳》以“信志”釋之，謂孚即信也，以其志之可信，故得吉也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：運得中正，眾心交孚，是以有吉，無悔。</p><p>○　問戰徵：上下一心，令出惟行，有匹夫不可奪之志，戰無不克，吉。</p><p>○　問營商：貿易雖在逐利，要必以信為本，有信則彼此無欺，而商業乃可通行矣。</p><p>○　問婚姻：二五相孚，是陰陽相偶也，吉。</p><p>○　問家宅：“有孚攣如，富以其鄰”，謂能與鄰家，併力致富也。</p><p>○　問功名：《中孚》二爻曰，“我有好爵，吾與爾靡之”，有父子同升之吉。</p><p>○　問疾病：是因疑致疾，今既得相孚，災悔自亡。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某來，請佔氣運，筮得《兌》之《隨》。</p><p>斷曰：九二爻得剛中，剛中而孚，孚非阿好；既得相孚，無不相悅，是以吉而悔亡也。人生氣運，亦貴得其剛中耳，剛則任事有肝膽，中則任事無私曲，志氣剛強，運途中正，自然事事獲吉。今足下佔得此爻，知足下目下氣運旺相。論《兌》為金運，以金水兩運為佳；《兌》為秋，歲時以屬秋令為佳。《大象》取“朋友講習”，足下當擇朋友，遠小人，近君子，自得相扶為益，悔去而吉來也。</p><p>明治二十八年，佔我國與美國交際，筮得《兌》之《隨》。</p><p>斷曰：孚者，信也，《中孚》《彖傳》曰“悅而巽，孚乃化邦”，是知邦交之道，最宜信義相孚，使兩無詐虞，化干戈為玉帛，實兩邦之幸福也。今佔我國與美國交際，得此爻辭，可知我國與美，兩國交際，此後最為親密，謂之“孚兌，吉，悔亡”。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三為《兌》主，即《彖》所謂“柔外”也。以柔招悅，故謂之“來”。初曰“和”，二曰“孚”，是不期悅而自悅，有相悅於無言耳。若專以陰柔悅人，亦以陰柔而致人悅，則所以來悅者，皆不以其道，則上下相蒙，適以長詐偽之風也，故“兇”。《傳》以“不當位”釋之，謂一陰居二陽之上，其位不當，欲以柔道致悅，其悅也，皆由強致而來，是失剛中之德矣。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：人品卑鄙，專以諂笑求悅，未免為人所賤矣。</p><p>○　問營商：通商之來，固宜和悅相招，然悅不以道，爾詐我虞，是失商道之正也。</p><p>○　問功名：奔競而來，雖榮必敗。</p><p>○　問戰徵：要皆招徠烏合之眾也，不能久持。</p><p>○　問婚姻：有始合終離之象。</p><p>○　問疾病：病有外祟，其象本兇，三至四隔一爻，早則一日，遲則一月，可望愈快。</p><p>○　問訟事：是外來之禍，兇。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>明治二十四年，有友某來，代佔某氏氣運，筮得《兌》之《夬》。</p><p>斷曰：兌者，悅也，其悅宜就心中而出，不貴外襲而來。中出者，誠也，外來者，偽也。三曰“來兌”，是專以飾外為悅者也。今君代友佔氣運，得《兌》三爻，三以陰居陽，為《兌》之主，位本不當，其象專屬陰柔，好以巧言悅人，知此友心地不正，頗有口密腹劍之象，未免兇矣。《大象》曰“朋友講習”，君既誼屬朋友，當隨時勸誡，務令去偽存誠，乃得化兇為吉。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“介”，謂節操堅固之義，同《豫》之六二“介於石”之介；又兩間曰介，四爻在三五之間，上承五之剛中，下比三之陰柔，是以一身介君子小人之間者也。“商”，商量也，《兌》為口，有商之象。四與初同體，初為事始，無所疑慮，故不待商；四則處上下之交，用剛用柔，皆須商榷，故曰“商兌”。商之而意難遽定，則中心遊移，故曰“未寧”。因憂成病，故曰“介疾”。然未寧者終必寧，介然而疾，亦介然而喜矣。《兌》通《艮》，《艮》上《兌》下為《損》，《損》四曰“損其疾，使遄有喜”，其旨相同。《象傳》以“有慶”釋之，謂商而後寧，疾而有喜，則剛柔得中，天人相合，喜在一人，慶在天下矣。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：運途未穩，逆則有憂，順則有喜，萬事宜斟酌行之。</p><p>○　問營商：“四多懼”，營商在外，必有憂懼不安之事，商量出之，方得有喜。</p><p>○　問功名：功名必從艱苦患難而來者，方得大就。</p><p>○　問婚姻：一時疑懼未成，必待媒妁再三說合，終得成合有喜。</p><p>○　問家宅：現下宅中不安，致多疾厄。《兌》為秋，必待秋時，得以平安有喜。</p><p>○　問疾病：病由心神不安所致，得逢喜事，胸懷寬悅自愈。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某氏來，請佔某縉神之氣運，筮得《兌》之《節》。</p><p>斷曰：兌者，悅也，“未寧”者，不悅也，兌而曰“商”，是介在悅不悅之中。“未寧”若有疾，得寧則有喜，賴此一商之功耳。四處內外之間，又當剛柔之交，孰輕孰重，皆須商酌，故曰“商兌未寧，介疾有喜”。今佔氣運，得《兌》四爻，知人生氣運，亦無中立，從正則吉，從邪則兇，在人自取擇耳。擇而未安，譬若疾之在身，不能無憂，擇之既定，自覺病去身安，喜從中來。四近君位，有貴人之象，能以商度事宜，上輔君德，下協民心，何慶如之？此功此德，正賴某縉紳也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五處外卦之中，秉《乾》之剛，即《彖傳》所謂“剛中”也，悅以“利貞”，五得其貞焉。《兌》為秋，《剝》九月之卦，當《兌》之未孚而至《剝》，是孚之極也。其不言《兌》者，至五《兌》悅既深，渾若相忘，故不見為《兌》，而只見為《剝》。《剝》者即勞與難之事也，勞之難之，事雖為民，而王者則視之若剝也；忘勞忘死，王者雖以為剝，而民實不知其為剝也，故曰“孚於剝”。至此而民已視危為安，王者猶以安為危，故曰“有厲”。事本無厲，有者在君之心，亦凜凜乎其有也。五居尊位，固當然也。《傳》釋以“位正當”，謂居此位者，皆當存此心也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：位得其正，運當其盛，盛極則剝，尤當預防，能時時防剝，斯時時得盛矣。</p><p>○　問戰徵：“孚於剝”者，謂當生死存亡之地，軍兵一心，感激奮勇，而不以為剝，誠可謂眾志成城，無往不克矣。</p><p>○　問營商：剝者，剝削也，雖有剝削，而深信無疑，必有大利。</p><p>○　問功名：能安命，雖剝必亨。</p><p>○　問疾病：有剝膚之疾，速治則愈。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十二年，友人某來，請佔氣運，筮得《兌》之《歸妹》。</p><p>斷曰：運當九五，陽剛中正，本屆盛運，爻曰“孚於剝”，言其相悅無言，雖剝亦孚。安不忘危，有思患預防之象，亦有持盈保泰之道，《彖傳》所謂“悅以利貞”，惟五當之。今君佔氣運，得《兌》五爻，知君目下氣運得當，剛中柔外，眾心鹹孚，雖有剝削，亦得相悅以解，事事安和，得行其志。但在君心中，若以為剝，若以為厲，則剝無不復，厲無不安也。五與二正應，五雖不言吉，二之吉，即五之吉也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上六辰在巳，得《巽》氣，《巽》為繩，有引之象；《兌》又旁通《艮》，《艮》為手，是以能引，故曰“引兌”。六與三同體，三失位，六引之使應己，是因其來而引之；來既不正，引亦不當，而悅更失其道矣。爻雖未判吉凶，要之後事之失，亦所難免，故《傳》以“未光”釋之。《乾》為光，六變《乾》為《坤》，故曰“未光”。凡《易》稱“引”者，多在陰爻，《萃》六二曰“引吉”，自五引二，引而升也，引在於上，故吉；此爻曰“引兌”，以六引三，引其來也，引在於後，故“未光”。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：上為卦之終，行運已極，必藉人引掖而能行，無吉無兇，平平而已。</p><p>○　問功名：雖得他人薦引，亦已晚矣。</p><p>○　問營商：得人引導，方可交易，上在卦外，是出洋經營也。“未光”者，未能大得利也。</p><p>○　問戰徵：《兌》屬正西，“引兌”者，相引而入西也。是引兵向西，與三合隊，但當上爻，時會已遲，恐未必能奏功也。</p><p>○　問疾病：內邪能引而外達，乃得望愈。</p><p>○　問家宅：宅地純陰，與三合體，防有內外牽引之患。</p><p>○　問婚姻：爻象皆柔，恐是勾引而成，非夫婦之正禮也。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十二年，佔某貴顯氣運，筮得《兌》之《履》。</p><p>斷曰：上爻處外卦之極，無可復進，凡物極則變，有反而思退之象焉。今某貴顯佔得此爻，知貴顯久居高位，意將引身退隱，以自娛樂，謂之“引兌”。是年冬，某貴顯辭職歸隱。</p>',104)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
